51	// rememberSessionEnv lets agent/hook callers pass the session id through
52	// the environment when the --session flag is not plumbable.
53	const rememberSessionEnv = "ENTIRE_BRAIN_SESSION_ID"
54	
55	// rememberSessionID resolves the session an authored fact was created in:
56	// --session, then $ENTIRE_BRAIN_SESSION_ID. A human running `remember` in a
57	// terminal legitimately has neither; an absent SessionID stays valid.
58	func rememberSessionID(rememberOpts rememberCommandOptions) string {
59		if session := strings.TrimSpace(rememberOpts.session); session != "" {
60			return session
61		}
62		return strings.TrimSpace(os.Getenv(rememberSessionEnv))
63	}
