65	// rememberAnchorCommit resolves the commit an authored fact should cite.
66	//
67	// `remember --branch <other>` files the fact on ANOTHER branch without moving
68	// the working tree, so HEAD is the wrong evidence: it is the CURRENT branch's
69	// tip, and it may not be on <other> at all. The stored fact then reads "on
70	// <other>, evidenced by <a commit that branch never had>" — and verification
71	// launders it, because verifyCommitUncached accepts reachability from ANY local
72	// ref rather than from the fact's branch.
73	//
74	// With an explicit override the named branch's tip is the only honest answer,
75	// and a branch git cannot resolve yields NO commit: an absent anchor is honest
76	// (verify reports it as unverifiable), a wrong one is not. Without an override
77	// the branch was derived from HEAD in the first place, so HEAD stays the
78	// answer — which also keeps a detached HEAD, where there is no branch to
79	// resolve, citing the commit actually checked out.
80	func rememberAnchorCommit(ctx context.Context, opts Options, repoDir, branch string, explicit bool) (string, bool) {
81		args := []string{"rev-parse", "HEAD"}
82		if explicit {
83			args = []string{"rev-parse", "--verify", branch + "^{commit}"}
84		}
85		commit, err := base.GitScalar(ctx, opts.Runner, repoDir, args...)
86		if err != nil {
87			return "", false
88		}
89		commit = strings.TrimSpace(commit)
90		return commit, commit != ""
91	}
