51	// rememberSessionEnv lets agent/hook callers pass the session id through
52	// the environment when the --session flag is not plumbable.
53	const rememberSessionEnv = "ENTIRE_BRAIN_SESSION_ID"
54	
55	// rememberSessionID resolves the session an authored fact was created in:
56	// --session, then $ENTIRE_BRAIN_SESSION_ID. A human running `remember` in a
57	// terminal legitimately has neither; an absent SessionID stays valid.
58	func rememberSessionID(rememberOpts rememberCommandOptions) string {
59		if session := strings.TrimSpace(rememberOpts.session); session != "" {
60			return session
61		}
62		return strings.TrimSpace(os.Getenv(rememberSessionEnv))
63	}
64	
65	// rememberAnchorCommit resolves the commit an authored fact should cite.
66	//
67	// `remember --branch <other>` files the fact on ANOTHER branch without moving
68	// the working tree, so HEAD is the wrong evidence: it is the CURRENT branch's
69	// tip, and it may not be on <other> at all. The stored fact then reads "on
70	// <other>, evidenced by <a commit that branch never had>" — and verification
71	// launders it, because verifyCommitUncached accepts reachability from ANY local
72	// ref rather than from the fact's branch.
73	//
74	// With an explicit override the named branch's tip is the only honest answer,
75	// and a branch git cannot resolve yields NO commit: an absent anchor is honest
76	// (verify reports it as unverifiable), a wrong one is not. Without an override
77	// the branch was derived from HEAD in the first place, so HEAD stays the
78	// answer — which also keeps a detached HEAD, where there is no branch to
79	// resolve, citing the commit actually checked out.
80	func rememberAnchorCommit(ctx context.Context, opts Options, repoDir, branch string, explicit bool) (string, bool) {
81		args := []string{"rev-parse", "HEAD"}
82		if explicit {
83			args = []string{"rev-parse", "--verify", branch + "^{commit}"}
84		}
85		commit, err := base.GitScalar(ctx, opts.Runner, repoDir, args...)
86		if err != nil {
87			return "", false
88		}
89		commit = strings.TrimSpace(commit)
90		return commit, commit != ""
91	}
92	
93	func runRemember(ctx context.Context, cmd *cobra.Command, opts Options, rememberOpts rememberCommandOptions, text string) error {
94		text = strings.TrimSpace(text)
95		if text == "" {
96			return fmt.Errorf("memory text must not be empty")
97		}
98		// A fact that is not about one repository has nowhere to go in a per-repo
99		// store, and outside a checkout there is no store at all. Both cases file
100		// globally: explicitly when asked, and automatically rather than refusing,
101		// because "you are not in a repository" is a reason to pick a different
102		// store, not a reason to discard what somebody just typed.
103		global := rememberOpts.global
104		if !global && strings.TrimSpace(rememberOpts.branch) == "" {
105			here, err := inARepository(ctx, opts)
106			if err != nil {
107				// An undecidable repository identity is not an invitation to file
108				// the fact somewhere else. Surfacing it is the whole point of the
109				// guard that raised it.
110				return err
111			}
112			if !here {
113				global = true
114				fmt.Fprintln(cmd.ErrOrStderr(), globalFactNotice(false))
115			}
116		}
117	
118		var (
119			repoDir  string
120			brainDir string
121			branch   string
122			err      error
123		)
124		if global {
125			if strings.TrimSpace(rememberOpts.branch) != "" {
126				// A global fact is not on a branch, and quietly ignoring --branch
127				// would file it somewhere the user did not ask for.
128				return fmt.Errorf("--global and --branch cannot be combined: a global memory is not on a branch")
129			}
130			brainDir, branch, err = resolveGlobalFactsTarget(opts.Env)
131			if err != nil {
132				return err
133			}
134			// repoDir stays empty on purpose: classification and the commit anchor
135			// below both degrade to "no repository", which is the truth.
136			repoDir = ""
137		} else {
138			repoDir, brainDir, branch, err = resolveFactsTarget(ctx, opts, agentSurfaceTarget(opts, nil), rememberOpts.branch)
139			if err != nil {
140				return err
141			}
142		}
143		now := opts.Now().UTC()
144		taxonomy, err := loadFactTaxonomy(brainDir, now)
145		if err != nil {
146			return err
147		}
148	
149		paths, err := resolveRememberPaths(ctx, opts, rememberOpts, repoDir, text, taxonomy)
150		if err != nil {
151			return err
152		}
153	
154		if err := validateKindFlag(rememberOpts.kind); err != nil {
155			return err
156		}
157		explicitKind := strings.ToLower(strings.TrimSpace(rememberOpts.kind))
158		kind := explicitKind
159		if kind == "" {
160			kind = inferFactKind(paths, text)
161		}
162	
163		anchor := factAnchor{}
164		// A global fact has no provenance to cite: a commit from whatever happened
165		// to be checked out would be laundered by verification, and a session id is
166		// repo-scoped — stamping it on a record in the cross-repo store leaks one
167		// repository's session into every repository's recall.
168		if !global {
169			anchor.SessionID = rememberSessionID(rememberOpts)
170			if commit, ok := rememberAnchorCommit(ctx, opts, repoDir, branch, strings.TrimSpace(rememberOpts.branch) != ""); ok {
171				anchor.Commit = commit
172			}
173		}
174	
175		record := factRecord{
176			ID:         factRecordID(text, paths),
177			Paths:      paths,
178			Kind:       kind,
179			Locus:      base.FactLocus(text),
180			Text:       text,
181			Branch:     branch,
182			Origin:     factOriginAuthored,
183			Status:     factStatusActive,
184			Provenance: []factAnchor{anchor},
185			CreatedAt:  now,
186			UpdatedAt:  now,
187		}
188	
189		storedKind := kind
190		if err := brainstore.WithBrainWriteLock(brainDir, func() error {
191			facts, err := loadFacts(brainDir, branch)
192			if err != nil {
193				return err
194			}
195			facts = upsertFact(facts, record)
196			if i := indexOfFact(facts, record.ID); i >= 0 {
197				// Re-authoring is a deliberate human assertion that the statement is
198				// true again. A fact id is content-derived, so `remember` of a
199				// statement that was previously retracted (or superseded) matches the
200				// retired record, and upsertFact only unions provenance — it never
201				// revives a status, which is exactly right for a re-distill but wrong
202				// here: without this the command prints "remembered ..." while the
203				// fact stays invisible to recall, and the author's write is silently
204				// lost. Reviving keeps the record and its history; it only restores
205				// the status the author just asserted.
206				if facts[i].Status != factStatusActive {
207					facts[i].Status = factStatusActive
208					facts[i].SupersededBy = ""
209					facts[i].UpdatedAt = now
210				}
211				// An explicit --kind is a deliberate human correction and must win even
212				// when the fact already exists, where upsertFact's anti-thrash rule would
213				// otherwise keep the stored kind. The reported kind is then always the one
214				// actually persisted, never a discarded request.
215				if explicitKind != "" {
216					facts[i].Kind = explicitKind
217				}
218				storedKind = factKindOrInferred(facts[i])
219				record = facts[i]
220			}
221			if err := writeFacts(brainDir, branch, facts); err != nil {
222				return err
223			}
224			if err := writeFactTaxonomy(brainDir, taxonomy); err != nil {
225				return err
226			}
227			return updateFactSourceManifestLocked(brainDir, now)
228		}); err != nil {
229			return err
230		}
231	
232		record.Kind = storedKind // report what was actually persisted
233		// After the write, never before: a subscriber must not be told about a fact
234		// that failed to persist. Delivery cannot fail this command — the fact is
235		// already on disk and the author's write must not be undone by an
236		// unreachable endpoint.
237		if global {
238			webhook.NotifyGlobalFactWebhook(ctx, cmd.ErrOrStderr(), webhook.WebhookFactRecorded, record, now)
239		} else {
240			webhook.NotifyFactWebhook(ctx, cmd.ErrOrStderr(), opts, webhook.WebhookFactRecorded, branch, record, now)
241		}
242		if rememberOpts.json {
243			return cmdutil.WriteJSON(cmd, record)
244		}
245		where := "on " + branch
246		if global {
247			where = "globally"
248		}
249		fmt.Fprintf(cmd.OutOrStdout(), "remembered %s [%s] %s %s\n", record.ID, storedKind, strings.Join(paths, ","), where)
250		return nil
251	}
