253	// resolveRememberPaths returns the taxonomy paths for an authored fact: the
254	// explicit --path when given, otherwise the agent's classification. Without an
255	// agent and without --path it errors, mirroring the plan's contract.
256	func resolveRememberPaths(ctx context.Context, opts Options, rememberOpts rememberCommandOptions, repoDir, text string, taxonomy factTaxonomy) ([]string, error) {
257		if strings.TrimSpace(rememberOpts.path) != "" {
258			paths := normalizeFactPaths(strings.Split(rememberOpts.path, ","))
259			if len(paths) == 0 {
260				return nil, fmt.Errorf("--path %q is not a valid taxonomy path (category.subcategory.type)", rememberOpts.path)
261			}
262			// Explicit paths must all sit under a known top-level category, exactly
263			// like agent-classified ones — otherwise --path can mint
264			// immediately-orphaned facts the rest of the system treats as invalid.
265			// Unlike the agent path (where unknown categories are dropped as noise),
266			// an explicit --path is deliberate, so any unknown category is a hard
267			// error rather than a silent drop that would hide a typo. New
268			// three-level paths under an existing category are still allowed.
269			var warnings []string
270			filtered := filterFactPathsByTaxonomy(paths, taxonomy, &warnings)
271			if len(filtered) != len(paths) {
272				return nil, fmt.Errorf("--path %q is not under a known taxonomy category (%s)", rememberOpts.path, strings.Join(sortedTaxonomyTopLevels(taxonomy), ", "))
273			}
274			return filtered, nil
275		}
276	
277		agent := rememberOpts.agent
278		if agent == "auto" {
279			agent = defaultRefreshAgent(ctx, opts.Runner, repoDir)
280		}
281		if agent == "none" || agent == "" {
282			return nil, fmt.Errorf("no agent available to classify; pass --path <category.subcategory.type>")
283		}
284		args, err := base.DistillAgentCommandArgs(agent, rememberOpts.agentCommand, classifyPrompt(taxonomy))
285		if err != nil {
286			return nil, err
287		}
288		args = base.InjectAgentModel(args, agent, rememberOpts.model)
289		run := rememberOpts.run
290		if run == nil {
291			run = defaultDistillAgentRunner(agent)
292		}
293		out, err := run(ctx, repoDir, args, []byte(text), defaultDistillTimeout)
294		if err != nil {
295			return nil, fmt.Errorf("classify memory: %w; pass --path to classify manually", err)
296		}
297		paths := parseClassifyOutput(out, taxonomy)
298		if len(paths) == 0 {
299			return nil, fmt.Errorf("agent did not return a valid taxonomy path; pass --path")
300		}
301		return paths, nil
302	}
303	
304	// classifyPrompt instructs the agent to assign a taxonomy path to a single fact
305	// supplied on stdin. Like the other agent prompts it must not begin with a dash.
306	func classifyPrompt(taxonomy factTaxonomy) string {
307		return "Classify the durable repository fact on stdin into the taxonomy below. " +
308			"Output exactly one line: one taxonomy path, or two comma-separated paths only if the fact genuinely spans two top-level categories. " +
309			"Each path is three lowercase segments: category.subcategory.type. Invent a new three-level path only under an existing top-level category. " +
310			"Output only the path line, no prose.\n\n" + factTaxonomyBlock(taxonomy)
311	}
312	
313	// parseClassifyOutput extracts taxonomy paths from the classifier's response:
314	// the first line containing a valid path, comma- or whitespace-separated,
315	// filtered to known top-level categories and capped at two.
316	func parseClassifyOutput(output string, taxonomy factTaxonomy) []string {
317		for _, line := range strings.Split(output, "\n") {
318			line = strings.TrimSpace(line)
319			if line == "" {
320				continue
321			}
322			fields := strings.FieldsFunc(line, func(r rune) bool { return r == ',' || r == ' ' || r == '\t' })
323			paths := normalizeFactPaths(fields)
324			var warnings []string
325			paths = filterFactPathsByTaxonomy(paths, taxonomy, &warnings)
326			if len(paths) > 0 {
327				return paths
328			}
329		}
330		return nil
331	}
