43	// resolveFactsTarget resolves the repo, brain directory, and the branch facts
44	// are scoped to (the live git branch unless overridden). It is shared by the
45	// fact read/write commands.
46	func resolveFactsTarget(ctx context.Context, opts Options, target, branchOverride string) (repoDir, brainDir, branch string, err error) {
47		repoDir, local, err := base.ResolveLocalTargetRepoDir(ctx, opts.Runner, target)
48		if err != nil {
49			return "", "", "", err
50		}
51		if !local {
52			return "", "", "", fmt.Errorf("memories require a local repository path: %s", target)
53		}
54		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
55		if err != nil {
56			return "", "", "", err
57		}
58		branch = strings.TrimSpace(branchOverride)
59		if branch == "" {
60			if current, gitErr := base.GitScalar(ctx, opts.Runner, repoDir, "branch", "--show-current"); gitErr == nil {
61				branch = strings.TrimSpace(current)
62			}
63		}
64		if branch == "" {
65			branch = distillDefaultBranch
66		}
67		return repoDir, storage.BrainDir, branch, nil
68	}
