73	func newRecallCommand(opts Options) *cobra.Command {
74		var evidence bool
75		var evidenceBytes int
76		var (
77			branch                string
78			limit                 int
79			includeAll            bool
80			scope                 string
81			kind                  string
82			locus                 string
83			noSemantic            bool
84			expand                bool
85			agent                 string
86			model                 string
87			agentCommand          []string
88			jsonOut               bool
89			eligibleBefore        string
90			sessionDatesPath      string
91			excludeSessionIDs     []string
92			readOnlySemanticCache bool
93			noGlobal              bool
94		)
95		cmd := &cobra.Command{
96			Use:   "recall <query>",
97			Short: "Retrieve durable memories matching a query for the current branch",
98			Args:  cobra.MaximumNArgs(1),
99			RunE: func(cmd *cobra.Command, args []string) error {
100				query := ""
101				if len(args) == 1 {
102					query = args[0]
103				}
104				if evidence {
105					for _, flag := range []string{"all", "scope", "kind", "locus", "expand", "agent", "model", "agent-command", "eligible-before", "session-dates", "exclude-session-id", "read-only-semantic-cache"} {
106						if cmd.Flags().Changed(flag) {
107							return fmt.Errorf("--%s is not supported with --evidence; evidence recall is deterministic and does not apply memory filters", flag)
108						}
109					}
110				} else if cmd.Flags().Changed("evidence-bytes") {
111					return fmt.Errorf("--evidence-bytes requires --evidence")
112				}
113				if err := validateScopeFlag(scope); err != nil {
114					return err
115				}
116				if err := validateKindFlag(kind); err != nil {
117					return err
118				}
119				repoDir, brainDir, resolvedBranch, err := resolveFactsTarget(cmd.Context(), opts, agentSurfaceTarget(opts, nil), branch)
120				if err != nil {
121					return err
122				}
123				if evidence {
124					return runRecallEvidence(cmd, brainDir, resolvedBranch, query, limit, evidenceBytes, jsonOut)
125				}
126				allFacts, err := loadFacts(brainDir, resolvedBranch)
127				if err != nil {
128					return err
129				}
130				// Facts that are not about this repository — preferences, team
131				// conventions, environment details — merge in here, so something
132				// recorded once applies everywhere. They go through every filter
133				// and the same ranking as repository facts; the only difference is
134				// that they are labelled, because acting on a global convention as
135				// though this repo had declared it is a different thing.
136				globalIDs := map[string]bool{}
137				if globalFactsEnabled(noGlobal) {
138					globalFacts, globalErr := loadGlobalFacts(opts.Env)
139					if globalErr != nil {
140						// A damaged global store must not take recall down with it;
141						// the repository's own facts are the answer to most queries.
142						fmt.Fprintf(cmd.ErrOrStderr(), "warning: global memories unavailable: %v\n", globalErr)
143					} else {
144						allFacts, globalIDs = mergeGlobalFacts(allFacts, globalFacts)
145					}
146				}
147				var storeWarning string
148				manifest, manifestErr := loadBrainManifest(brainDir)
149				if manifestErr != nil {
150					storeWarning = "memory source manifest unavailable: " + manifestErr.Error()
151				} else if manifest != nil && manifest.Sources != nil {
152					storeWarning = missingFactStoreWarningForBranch(brainDir, manifest.Sources.Facts, resolvedBranch)
153				}
154				candidateFacts := allFacts
155				var eligibility *factEligibilityAudit
156				if eligibleBefore != "" || sessionDatesPath != "" || len(excludeSessionIDs) > 0 {
157					if eligibleBefore == "" || sessionDatesPath == "" {
158						return fmt.Errorf("--eligible-before and --session-dates must be supplied together")
159					}
160					dates, loadErr := loadSessionDates(sessionDatesPath)
161					if loadErr != nil {
162						return loadErr
163					}
164					filtered, audit, filterErr := filterFactsByTemporalEligibility(allFacts, dates, eligibleBefore, excludeSessionIDs)
165					if filterErr != nil {
166						return filterErr
167					}
168					candidateFacts = filtered
169					eligibility = &audit
170				}
171				facts := filterFactsByLocus(filterFactsByKind(filterFactsByScope(candidateFacts, scope), kind), locus)
172				effectiveQuery := query
173				if expand && strings.TrimSpace(query) != "" {
174					resolved := agent
175					if resolved == "auto" {
176						resolved = defaultRefreshAgent(cmd.Context(), opts.Runner, repoDir)
177					}
178					expandArgs, expErr := base.DistillAgentCommandArgs(resolved, agentCommand, queryExpansionPrompt())
179					if expErr != nil {
180						return fmt.Errorf("expand agent: %w", expErr)
181					}
182					expandArgs = base.InjectAgentModel(expandArgs, resolved, model)
183					exp, expErr := expandQuery(cmd.Context(), defaultDistillAgentRunner(resolved), expandArgs, repoDir, query, loadExpansionCache(""))
184					if expErr != nil {
185						return fmt.Errorf("expand query: %w", expErr)
186					}
187					effectiveQuery = expandedQuery(query, exp)
188				}
189				// --no-semantic and --read-only-semantic-cache are vacuously
190				// satisfied since the semantic arm was removed (trail #278):
191				// ranking is always lexical and no vector cache exists to write.
192				_, _ = noSemantic, readOnlySemanticCache
193				matches := rankFacts(facts, effectiveQuery, limit, includeAll)
194				// Locus drift (Phase 2 item 4): flag surfaced facts whose code
195				// locus left the worktree, so the agent knows which to re-verify.
196				drift := factsLocusDrift(repoDir, factsEligibleForLocusDrift(matches, globalIDs))
197				// Live trust state: a surfaced fact with a pending merge/supersede
198				// proposal is annotated (not collapsed — recall keeps its record
199				// shape), matching the guard the unified query/search/get path
200				// applies. Groups are built from the unfiltered branch set so
201				// scope/kind/locus filters cannot hide a pending relationship.
202				// Nothing surfaced means no annotation and no queue warning, so skip
203				// the proposal read entirely on the empty-recall path.
204				var proposals []factProposal
205				var proposalsErr error
206				var pendingReviews map[string]factReviewNotice
207				if len(matches) > 0 {
208					proposals, proposalsErr = loadFactProposals(brainDir, resolvedBranch)
209					if proposalsErr == nil {
210						localFacts := factsEligibleForLocusDrift(allFacts, globalIDs)
211						pendingReviews = factsPendingReview(localFacts, proposals, matches)
212					}
213				}
214				recordReceipt := func() {
215					recordServedFacts(cmd.ErrOrStderr(), vitalityNow(opts), brainDir, resolvedBranch, "recall",
216						vitalityHead(cmd.Context(), opts.Runner, repoDir), query, factRecordIDs(matches))
217				}
218				if jsonOut {
219					// Recall's JSON envelope is fact-centric (top-level `facts`), so
220					// its fact-scoped keys stay unprefixed: `pending_reviews` and
221					// `locus_drift`. The brief report is a multi-domain object and
222					// prefixes the same concepts as `facts_pending_review` /
223					// `facts_locus_drift` to disambiguate. This per-surface split is
224					// intentional and kept as-is; we do not unify the keys.
225					out := map[string]any{"branch": resolvedBranch, "query": query, "facts": matches}
226					// A consumer that renders these has to be able to tell which
227					// facts came from outside this repository; the ids are the
228					// smallest way to say so without changing the fact shape that
229					// every existing reader binds to.
230					if ids := sortedGlobalFactIDs(matches, globalIDs); len(ids) > 0 {
231						out["global_fact_ids"] = ids
232					}
233					engine := recallRetrievalIdentity()
234					out["retrieval_engine"] = engine
235					if engine.EffectiveEngine != "" {
236						out["effective_engine"] = engine.EffectiveEngine
237					}
238					if eligibility != nil {
239						eligibility.DeliveredCount = len(matches)
240						out["eligibility"] = eligibility
241					}
242					if len(drift) > 0 {
243						out["locus_drift"] = drift
244					}
245					if len(pendingReviews) > 0 {
246						out["pending_reviews"] = pendingReviews
247					}
248					if proposalsErr != nil && len(matches) > 0 {
249						out["warnings"] = []string{factReviewQueueUnavailableWarning}
250					}
251					if storeWarning != "" {
252						warnings, _ := out["warnings"].([]string)
253						out["warnings"] = append(warnings, storeWarning)
254					}
255					if len(matches) == 0 {
256						if note := emptyResultBlindSpotOnBranch(brainDir, resolvedBranch); note != "" && storeWarning == "" {
257							out["blind_spot"] = note
258						}
259					}
260					if err := cmdutil.WriteJSON(cmd, out); err != nil {
261						return err
262					}
263					if len(matches) > 0 {
264						recordReceipt()
265					}
266					return nil
267				}
268				if len(matches) == 0 {
269					return cmdutil.WriteText(cmd, func(out io.Writer) {
270						fmt.Fprintf(out, "no memories for %q on %s\n", query, resolvedBranch)
271						if storeWarning != "" {
272							fmt.Fprintln(out, "warning: "+storeWarning)
273						}
274						if note := emptyResultBlindSpotOnBranch(brainDir, resolvedBranch); note != "" && storeWarning == "" {
275							fmt.Fprintln(out, note)
276						}
277					})
278				}
279				if err := cmdutil.WriteText(cmd, func(out io.Writer) {
280					if storeWarning != "" {
281						fmt.Fprintln(out, "warning: "+storeWarning)
282					}
283					if proposalsErr != nil {
284						fmt.Fprintf(out, "⚠ %s\n", factReviewQueueUnavailableWarning)
285					}
286					for _, f := range matches {
287						if globalIDs[f.ID] {
288							// Without this a global convention is indistinguishable
289							// from something this repository declared, and an agent
290							// would cite it as a property of the codebase.
291							printGlobalFactLine(out, f)
292						} else {
293							printFactLine(out, f)
294						}
295						if gone := drift[f.ID]; len(gone) > 0 {
296							fmt.Fprintf(out, "  ⚠ stale locus (no longer in worktree): %s\n", strings.Join(gone, ", "))
297						}
298						if notice, ok := pendingReviews[f.ID]; ok {
299							fmt.Fprintf(out, "  %s\n", factReviewNoticeLine(notice))
300						}
301					}
302				}); err != nil {
303					return err
304				}
305				recordReceipt()
306				return nil
307			},
308		}
309		cmd.Flags().BoolVar(&evidence, "evidence", false, "Experimental: return original source spans using deterministic retrieval; no model call")
310		cmd.Flags().IntVar(&evidenceBytes, "evidence-bytes", 8192, "Maximum compact JSON bytes in the evidence array, including citations; enclosing metadata is separate")
311		cmd.Flags().StringVar(&branch, "branch", "", "Branch to recall from (default: current branch)")
312		cmd.Flags().IntVar(&limit, "k", 10, fmt.Sprintf("Maximum memories to return, or candidate sessions with --evidence (1-%d)", recallMaxK))
313		cmd.Flags().BoolVar(&includeAll, "all", false, "Include superseded and retracted memories")
314		cmd.Flags().StringVar(&scope, "scope", "", "Restrict to 'local' (code/subsystem) or 'cross-cutting' (preferences/workflow) memories")
315		cmd.Flags().StringVar(&kind, "kind", "", "Restrict to one kind: decision|invariant|gotcha|preference|convention")
316		cmd.Flags().StringVar(&locus, "locus", "", "Restrict to memories about a code locus (a path or symbol, e.g. internal/cli/facts.go or factRecord)")
317		cmd.Flags().BoolVar(&noSemantic, "no-semantic", false, "Accepted for compatibility: semantic retrieval was removed, ranking is always BM25 lexical")
318		cmd.Flags().BoolVar(&expand, "expand", false, "Expand the query with agent-generated retrieval terms before ranking")
319		cmd.Flags().StringVar(&agent, "agent", "auto", "Agent for --expand: auto, codex, claude-code, ollama, or command")
320		cmd.Flags().StringVar(&model, "model", "", "Model for codex/claude-code/ollama expand calls")
321		cmd.Flags().StringArrayVar(&agentCommand, "agent-command", nil, "Agent command argv for --agent command")
322		cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit machine-readable JSON")
323		cmd.Flags().StringVar(&eligibleBefore, "eligible-before", "", "Restrict candidates to memories whose provenance is strictly before this RFC3339 cutoff")
324		cmd.Flags().StringVar(&sessionDatesPath, "session-dates", "", "JSON map of session IDs to provenance timestamps for --eligible-before")
325		cmd.Flags().StringArrayVar(&excludeSessionIDs, "exclude-session-id", nil, "Exclude memories anchored to this session (repeatable)")
326		cmd.Flags().BoolVar(&readOnlySemanticCache, "read-only-semantic-cache", false, "Accepted for compatibility: semantic vector caches no longer exist")
327		cmd.Flags().BoolVar(&noGlobal, "no-global", false, "Exclude global memories, recalling only this repository's")
328		return cmd
329	}
