394	// factsEligibleForLocusDrift drops global facts before the drift check.
395	//
396	// Locus drift asks whether a fact's code locus still exists in THIS worktree.
397	// A global fact was never scoped to this repository, so the answer is
398	// meaningless and always alarming: any path it mentions would be reported as a
399	// stale locus in every repository except the one it was written in. Global
400	// facts are excluded here for the same reason they are kept out of this
401	// repository's semantic cache.
402	func factsEligibleForLocusDrift(matches []factRecord, globalIDs map[string]bool) []factRecord {
403		if len(globalIDs) == 0 {
404			return matches
405		}
406		eligible := make([]factRecord, 0, len(matches))
407		for _, fact := range matches {
408			if !globalIDs[fact.ID] {
409				eligible = append(eligible, fact)
410			}
411		}
412		return eligible
413	}
414	
415	// printGlobalFactLine renders a fact that came from the global store rather than
416	// this repository.
417	func printGlobalFactLine(out io.Writer, f factRecord) {
418		marker := ""
419		switch f.Status {
420		case factStatusSuperseded:
421			marker = " (superseded)"
422		case factStatusRetracted:
423			marker = " (retracted)"
424		}
425		fmt.Fprintf(out, "%s %s [%s] (global)%s\n  %s\n", f.ID, factKindOrInferred(f), strings.Join(f.Paths, ","), marker, f.Text)
426	}
427	
428	// sortedGlobalFactIDs returns the ids of the surfaced facts that are global, in
429	// the order they were surfaced, so JSON output is stable across runs.
430	func sortedGlobalFactIDs(matches []factRecord, globalIDs map[string]bool) []string {
431		var ids []string
432		for _, f := range matches {
433			if globalIDs[f.ID] {
434				ids = append(ids, f.ID)
435			}
436		}
437		return ids
438	}
439	
440	// printFactLine renders a fact for human-readable listings.
441	func printFactLine(out io.Writer, f factRecord) {
442		marker := ""
443		switch f.Status {
444		case factStatusSuperseded:
445			marker = " (superseded)"
446		case factStatusRetracted:
447			marker = " (retracted)"
448		}
449		fmt.Fprintf(out, "%s %s [%s]%s\n  %s\n", f.ID, factKindOrInferred(f), strings.Join(f.Paths, ","), marker, f.Text)
450	}
