66		// is fact integrity, and without this it answered "0 orphaned" about a
67		// store that had lost a fact — it verified the facts it could still read
68		// and never asked whether that was all of them. Present only when the
69		// cross-check fails.
70		StoreIntegrity *factStoreIntegrity `json:"store_integrity,omitempty"`
71	}
