134		verifyOpts := verifyCommandOptions{limit: 10}
135		cmd := &cobra.Command{
136			Use:   "verify [<memory-id | query>]",
137			Short: "Verify durable memory anchors against local retained sources",
138			Args:  cobra.MaximumNArgs(1),
139			RunE: func(cmd *cobra.Command, args []string) error {
140				target := ""
141				if len(args) == 1 {
