149		cmd.Flags().BoolVar(&verifyOpts.all, "all", false, "Include superseded and retracted memories")
150		cmd.Flags().BoolVar(&verifyOpts.json, "json", false, "Emit machine-readable JSON")
151		cmd.Flags().BoolVar(&verifyOpts.strict, "strict", false, "Alias for --fail-on-unverifiable")
152		cmd.Flags().BoolVar(&verifyOpts.failOnUnverifiable, "fail-on-unverifiable", false, "Return nonzero when any matched memory is unverifiable-here (stale/orphaned always fail)")
