156	func runVerify(ctx context.Context, cmd *cobra.Command, opts Options, verifyOpts verifyCommandOptions, target string) error {
157		if verifyOpts.limit <= 0 {
158			return fmt.Errorf("--limit must be greater than 0")
159		}
160		repoDir, brainDir, branch, err := resolveFactsTarget(ctx, opts, agentSurfaceTarget(opts, nil), verifyOpts.branch)
161		if err != nil {
162			return err
163		}
164		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
165		if err != nil {
166			return err
167		}
168		report, err := buildVerifyReport(ctx, opts, repoDir, brainDir, storage.Key, branch, verifyOpts, target)
169		if err != nil {
170			return err
171		}
172		if verifyOpts.json {
173			if err := cmdutil.WriteJSON(cmd, report); err != nil {
174				return err
175			}
176		} else {
177			renderVerifyReportText(cmd, report)
178		}
179		if err := verifyFailureForReport(report, verifyOpts); err != nil {
180			return renderedCommandError{err: err}
181		}
182		return nil
183	}
184	
185	func verifyFailureForReport(report verifyReport, verifyOpts verifyCommandOptions) error {
186		// A store that cannot produce what the manifest declares fails verification
187		// unconditionally, and before the per-fact verdicts: those verdicts were
188		// computed over the survivors, so a clean sweep of them is not a pass. This
189		// matches how a corrupt history index behaves today — the read refuses and
190		// the command exits nonzero — rather than reporting success about a corpus
191		// it knows is short.
192		if report.StoreIntegrity != nil {
193			return errVerifyStoreIncomplete
194		}
195		if report.Summary.Stale > 0 || report.Summary.Orphaned > 0 {
196			return errVerifyIssues
197		}
198		if (verifyOpts.failOnUnverifiable || verifyOpts.strict) && report.Summary.UnverifiableHere > 0 {
199			return errVerifyStrictIssues
200		}
201		return nil
202	}
