204	func buildVerifyReport(ctx context.Context, opts Options, repoDir, brainDir, repoKey, branch string, verifyOpts verifyCommandOptions, target string) (verifyReport, error) {
205		manifest, err := loadBrainManifest(brainDir)
206		if err != nil {
207			return verifyReport{}, err
208		}
209		allFacts, err := loadFacts(brainDir, branch)
210		if err != nil {
211			return verifyReport{}, err
212		}
213		// A fact the store can no longer produce is not "0 orphaned" — it is a
214		// fact that is gone, and verify is the command that must say so. Check the
215		// manifest's claim against the store before verifying what survived, so
216		// the verdict below can never be read as a clean bill of health for a
217		// corpus that is short.
218		var storeIntegrity *factStoreIntegrity
219		if manifest != nil && manifest.Sources != nil {
220			if integrity := inspectFactStore(brainDir, manifest.Sources.Facts); !integrity.OK() {
221				storeIntegrity = &integrity
222			}
223		}
224		selected, query, err := selectFactsForVerify(allFacts, target, verifyOpts)
225		if err != nil {
226			return verifyReport{}, err
227		}
228		vctx := &verifyContext{
229			ctx:      ctx,
230			opts:     opts,
231			repoDir:  repoDir,
232			brainDir: brainDir,
233			branch:   branch,
234			manifest: manifest,
235		}
236		report := verifyReport{
237			SchemaVersion:  verifySchemaVersion,
238			GeneratedAt:    opts.Now().UTC(),
239			Repo:           brainStatusRepo{Root: repoDir, Key: repoKey},
240			BrainPath:      brainDir,
241			Branch:         branch,
242			Target:         strings.TrimSpace(target),
243			Query:          query,
244			Results:        []verifyFactResult{},
245			StoreIntegrity: storeIntegrity,
246		}
247		for _, fact := range selected {
248			result := vctx.verifyFact(fact)
249			report.Results = append(report.Results, result)
250			addVerifyResultToSummary(&report.Summary, result)
251		}
252		if verifyOpts.sample && target == "" {
253			selectable := 0
254			for _, fact := range allFacts {
255				if verifyOpts.all || fact.Status == factStatusActive {
256					selectable++
257				}
258			}
259			if selectable > len(selected) {
260				report.Summary.SampledOf = selectable
261			}
262		}
263		report.Warnings = append(report.Warnings, vctx.snapshotWarnings...)
264		return report, nil
265	}
266	
267	func selectFactsForVerify(facts []factRecord, target string, opts verifyCommandOptions) ([]factRecord, string, error) {
268		target = strings.TrimSpace(target)
269		if strings.HasPrefix(target, "fact:") {
270			i := indexOfFact(facts, target)
271			if i < 0 {
272				return nil, "", fmt.Errorf("no memory %s", target)
273			}
274			return []factRecord{facts[i]}, "", nil
275		}
276		if target != "" {
277			return rankFacts(facts, target, opts.limit, opts.all), target, nil
278		}
279		selected := make([]factRecord, 0, len(facts))
280		for _, fact := range facts {
281			if opts.all || fact.Status == factStatusActive {
282				selected = append(selected, fact)
283			}
284		}
285		if opts.sample && opts.limit > 0 && len(selected) > opts.limit {
286			// Most recently updated first: the facts an agent is most likely to
287			// consume next are the most valuable ones to spot-check.
288			sort.SliceStable(selected, func(i, j int) bool { return selected[i].UpdatedAt.After(selected[j].UpdatedAt) })
289			selected = selected[:opts.limit]
290		}
291		return selected, "", nil
292	}
293	
294	func (v *verifyContext) verifyFact(fact factRecord) verifyFactResult {
295		result := verifyFactResult{
296			Fact:    fact,
297			Verdict: verifyVerdictVerified,
298			Reason:  "all locally checkable anchors resolved",
299			Anchors: []verifyAnchorResult{},
300			Limitations: []verifyLimitation{{
301				Scope:   "turn-signature",
302				Verdict: verifyVerdictUnverifiableHere,
303				Reason:  verifyTurnSigningLimitation,
304			}},
305		}
306		if len(fact.Provenance) == 0 {
307			result.Verdict = verifyVerdictUnverifiableHere
308			result.Reason = "memory has no retained source anchor"
309			return result
310		}
311		// NO RECORD-LEVEL ORIGIN GATE. Both of the ones that used to live here
312		// bailed for the WHOLE fact, which is the wrong granularity for a record
313		// that can hold anchors of both kinds.
314		//
315		// factmerge.Upsert keys on the content id, independent of Origin, and
316		// keeps the existing record's Origin while unioning anchors. So a fact can
317		// end up Origin "imported" holding BOTH its foreign anchor and a genuine
318		// local one (a later distill of colliding text), and bailing on the record
319		// meant that real commit, checkpoint and transcript were never checked at
320		// all. The mirror case -- an authored record that gains a foreign anchor --
321		// is what the per-anchor check in verifyAnchor was added for; this is the
322		// same bug on the other side of the same merge.
323		//
324		// Per-anchor handles every case, and better:
325		//   foreign-shaped anchor -> unverifiable-here, naming the tool
326		//   genuine local anchor  -> checked normally
327		//   repo-shaped anchor on an "imported" record -> CHECKED, so a fabricated
328		//     commit is reported missing rather than described as an origin
329		//     contradiction and left unexamined
330		//
331		// That last one is why nothing is lost by dropping the contradiction
332		// message: actually resolving the anchor is a stronger answer than
333		// declaring it inconsistent.
334		factBranch := fact.Branch
335		if factBranch == "" {
336			factBranch = v.branch
337		}
338		for _, anchor := range fact.Provenance {
339			anchorResult := v.verifyAnchor(anchor, factBranch)
340			result.Anchors = append(result.Anchors, anchorResult)
341			result.Verdict = worseVerifyVerdict(result.Verdict, anchorResult.Verdict)
342		}
343		// Prefer a SPECIFIC anchor reason over the generic one.
344		//
345		// reasonForFactVerdict describes a verdict, not a cause: "one or more
346		// anchors need finer local evidence" is true of an imported fact, a
347		// turn-signature limitation and a sparse authored anchor alike, and tells
348		// the reader none of them apart. When every anchor that produced this
349		// verdict gives the SAME reason, that reason is the fact's reason, and it
350		// is the one the reader can act on.
351		//
352		// Only when they agree. Two different causes collapsed into one sentence
353		// would be a worse answer than the generic line, not a better one.
354		if specific := sharedAnchorReason(result.Anchors, result.Verdict); specific != "" {
355			result.Reason = specific
356		} else {
357			result.Reason = reasonForFactVerdict(result.Verdict)
358		}
359		return result
360	}
361	
362	// sharedAnchorReason returns the one reason given by every anchor carrying the
363	// fact's verdict, or "" when they disagree or none is set.
364	func sharedAnchorReason(anchors []verifyAnchorResult, verdict string) string {
365		reason := ""
366		for _, anchor := range anchors {
367			if anchor.Verdict != verdict {
368				continue
369			}
370			switch {
371			case strings.TrimSpace(anchor.Reason) == "":
372				return ""
373			case reason == "":
374				reason = anchor.Reason
375			case reason != anchor.Reason:
376				return ""
377			}
378		}
379		return reason
380	}
381	
382	func (v *verifyContext) verifyAnchor(anchor factAnchor, factBranch string) verifyAnchorResult {
383		result := verifyAnchorResult{Anchor: anchor, Verdict: verifyVerdictVerified, Reason: "anchor resolved locally", Checks: []verifyCheck{}}
384	
385		// PER-ANCHOR, because the record-level origin gates above are not enough.
386		//
387		// factmerge.Upsert keys on the content-addressed id and keeps the EXISTING
388		// record's Origin while unioning provenance. So an imported memory whose
389		// text and paths normalise onto a pre-existing authored fact -- which
390		// importing under an existing taxonomy prefix explicitly permits -- yields
391		// a fact with Origin != "imported" that nonetheless carries a foreign
392		// anchor. Neither origin gate fires, and this function then tries to
393		// resolve "mem0:abc" as a local session and reports the fact ORPHANED:
394		// "its evidence is gone", when its evidence was never here. That is the
395		// same false and alarming diagnosis the origin gates exist to prevent,
396		// reached by a different route.
397		//
398		// Per-anchor is also the correct granularity for that record: it holds the
399		// original local anchor AND the foreign one, so the local one must still be
400		// checked normally while the foreign one must not be called orphaned.
401		// worseVerifyVerdict then aggregates, and unverifiable-here does not mask a
402		// genuine local failure.
403		if anchorNamesAForeignSource(anchor) {
404			result.Verdict = verifyVerdictUnverifiableHere
405			result.Reason = "anchor names a session in " + strings.SplitN(strings.TrimSpace(anchor.SessionID), ":", 2)[0] + ", not this repository"
406			result.addCheck(verifyCheck{Name: "foreign_source", Verdict: verifyVerdictUnverifiableHere, Reason: result.Reason})
407			return result
408		}
409		hasRetainedSource := strings.TrimSpace(anchor.SessionID) != "" ||
410			strings.TrimSpace(anchor.CheckpointID) != "" ||
411			strings.TrimSpace(anchor.Transcript) != "" ||
412			anchor.Line > 0
413	
414		if strings.TrimSpace(anchor.Commit) != "" {
415			result.addCheck(v.verifyCommit(anchor.Commit))
416		}
417	
418		if !hasRetainedSource {
419			if result.Verdict == verifyVerdictOrphaned {
420				result.Reason = "commit anchor is missing locally"
421				return result
422			}
423			result.addCheck(verifyCheck{Name: "retained_source", Verdict: verifyVerdictUnverifiableHere, Reason: "authored memory has no retained source anchor"})
424			result.Reason = "authored memory has no retained source anchor"
425			return result
426		}
427	
428		session, sessionFound, sessionCheck := v.verifyExportedSession(anchor, factBranch)
429		result.addCheck(sessionCheck)
430		if !sessionFound {
431			result.Reason = sessionCheck.Reason
432			return result
433		}
434		if strings.TrimSpace(anchor.TurnID) != "" {
435			result.addCheck(verifyTurnID(session, anchor.TurnID))
436		}
437		if strings.TrimSpace(anchor.CheckpointID) != "" {
438			result.addCheck(v.verifyCheckpoint(anchor.CheckpointID))
439		}
440	
441		transcriptRel := strings.TrimSpace(anchor.Transcript)
442		if transcriptRel == "" {
443			transcriptRel = session.TranscriptPath
444		}
445		transcriptContent := ""
446		transcriptRead := false
447		if transcriptRel == "" {
448			result.addCheck(verifyCheck{Name: "transcript", Verdict: verifyVerdictOrphaned, Reason: "anchor has no transcript path"})
449		} else {
450			if session.TranscriptPath != "" && anchor.Transcript != "" && filepath.ToSlash(session.TranscriptPath) != filepath.ToSlash(anchor.Transcript) {
451				result.addCheck(verifyCheck{Name: "transcript_path", Verdict: verifyVerdictStale, Reason: fmt.Sprintf("exported session now points at %s", session.TranscriptPath)})
452			}
453			data, err := readCanonicalHistoryTranscript(v.ctx, v.brainDir, transcriptRel)
454			if err != nil {
455				result.addCheck(verifyCheck{Name: "transcript", Verdict: verifyVerdictOrphaned, Reason: err.Error()})
456			} else {
457				transcriptContent = string(data)
458				transcriptRead = true
459				result.addCheck(verifyCheck{Name: "transcript", Verdict: verifyVerdictVerified, Reason: transcriptRel})
460			}
461		}
462		if anchor.Line > 0 && transcriptRead {
463			line, ok := transcriptLine(transcriptContent, anchor.Line)
464			if !ok {
465				result.addCheck(verifyCheck{Name: "line", Verdict: verifyVerdictOrphaned, Reason: fmt.Sprintf("line %d is outside transcript", anchor.Line)})
466			} else {
467				result.LineExcerpt = base.TruncateString(strings.Join(strings.Fields(line), " "), 200)
468				result.addCheck(verifyCheck{Name: "line", Verdict: verifyVerdictVerified, Reason: fmt.Sprintf("line %d resolved", anchor.Line)})
469			}
470		}
471		if strings.TrimSpace(anchor.CheckpointID) != "" && transcriptRead {
472			result.addCheck(v.verifyCheckpointTranscript(anchor, session, transcriptContent))
473		}
474		result.Reason = reasonForAnchorVerdict(result.Verdict)
475		return result
476	}
477	
478	func (r *verifyAnchorResult) addCheck(check verifyCheck) {
479		if check.Name == "" {
480			return
481		}
482		r.Checks = append(r.Checks, check)
483		r.Verdict = worseVerifyVerdict(r.Verdict, check.Verdict)
484	}
485	
486	func (v *verifyContext) verifyCommit(commit string) verifyCheck {
487		commit = strings.TrimSpace(commit)
488		if commit == "" {
489			return verifyCheck{}
490		}
491		// Anchors are data: a crafted "commit" like --upload-pack=... must never
492		// reach git argv. Hex object ids only, matching the repo's hardening.
493		if !verifyCommitIDPattern.MatchString(commit) {
494			return verifyCheck{Name: "commit", Verdict: verifyVerdictOrphaned, Reason: "anchor commit is not a valid commit id"}
495		}
496		if cached, ok := v.commitChecks[commit]; ok {
497			return cached
498		}
499		check := v.verifyCommitUncached(commit)
500		if v.commitChecks == nil {
501			v.commitChecks = map[string]verifyCheck{}
502		}
503		v.commitChecks[commit] = check
504		return check
505	}
506	
507	var verifyCommitIDPattern = regexp.MustCompile(`^[0-9a-fA-F]{4,64}$`)
508	
509	func (v *verifyContext) verifyCommitUncached(commit string) verifyCheck {
510		// Verification is defined over locally retained evidence. Both existence
511		// and reachability can traverse promisor objects, so guard every Git object
512		// read against lazy network fetches just like checkpoint transcript reads.
513		if _, _, err := runCheckpointGitWithPolicy(v.ctx, v.opts.Runner, v.repoDir, true, "cat-file", "-e", commit+"^{commit}"); err != nil {
514			return verifyCheck{Name: "commit", Verdict: verifyVerdictOrphaned, Reason: "commit is missing locally"}
515		}
516		stdout, _, err := runCheckpointGitWithPolicy(v.ctx, v.opts.Runner, v.repoDir, true, "for-each-ref", "--format=%(refname)", "--contains", commit, "refs/heads", "refs/remotes", "refs/tags")
517		if err != nil {
518			return verifyCheck{Name: "commit", Verdict: verifyVerdictOrphaned, Reason: "commit reachability could not be checked locally"}
519		}
520		if strings.TrimSpace(string(stdout)) == "" {
521			return verifyCheck{Name: "commit", Verdict: verifyVerdictOrphaned, Reason: "commit is not reachable from local refs"}
522		}
523		return verifyCheck{Name: "commit", Verdict: verifyVerdictVerified, Reason: "commit exists and is reachable from local refs"}
524	}
525	
526	func (v *verifyContext) verifyExportedSession(anchor factAnchor, factBranch string) (exportSession, bool, verifyCheck) {
527		sessionID := strings.TrimSpace(anchor.SessionID)
528		if sessionID == "" {
529			return exportSession{}, false, verifyCheck{Name: "session", Verdict: verifyVerdictOrphaned, Reason: "anchor has no session_id"}
530		}
531		if v.manifest == nil || v.manifest.Sources == nil || v.manifest.Sources.Sessions == nil {
532			return exportSession{}, false, verifyCheck{Name: "session", Verdict: verifyVerdictOrphaned, Reason: "exported sessions source is missing"}
533		}
534		var bySession []exportSession
535		for _, session := range v.manifest.Sources.Sessions.Sessions {
536			if session.SessionID != sessionID {
537				continue
538			}
539			if factBranch != "" && resolveDistillBranch(v.manifest, session) != factBranch {
540				continue
541			}
542			bySession = append(bySession, session)
543		}
544		if len(bySession) > 0 {
545			// One session id can span SEVERAL exported rows — the same session
546			// exported on more than one branch — and a fact with no branch of its own
547			// keeps all of them. Which row is returned decides the transcript and the
548			// turn id every later check reads, so it may never be "whichever the
549			// manifest listed first".
550			if anchor.CheckpointID == "" {
551				return pickExportedSession(v.manifest, bySession), true, verifyCheck{Name: "session", Verdict: verifyVerdictVerified, Reason: "session is present in exported sessions"}
552			}
553			if row, ok := exportedSessionAtCheckpoint(v.manifest, bySession, anchor.CheckpointID); ok {
554				return row, true, verifyCheck{Name: "session", Verdict: verifyVerdictVerified, Reason: "session is present in exported sessions"}
555			}
556			// The anchor names a checkpoint that is not the session's latest. That
557			// is not automatically staleness: provenance sharpening deliberately
558			// anchors a fact to the checkpoint that actually changed the entity,
559			// which is usually mid-session. It is only stale if the checkpoint does
560			// not belong to this session at all.
561			//
562			// Verifying it requires knowing WHICH row owns it. With several rows and
563			// no way to tell them apart, the honest answer is the pre-sharpening one
564			// — stale — rather than an arbitrary row promoted to verified.
565			if member, owned := v.sessionCheckpoint(sessionID, anchor.CheckpointID); owned {
566				if row, ok := exportedSessionOwning(v.manifest, bySession, member); ok {
567					return row, true, verifyCheck{
568						Name:    "session",
569						Verdict: verifyVerdictVerified,
570						Reason:  fmt.Sprintf("session is present in exported sessions; anchor names its checkpoint %s", anchor.CheckpointID),
571					}
572				}
573			}
574			row := pickExportedSession(v.manifest, bySession)
575			return row, true, verifyCheck{Name: "session", Verdict: verifyVerdictStale, Reason: fmt.Sprintf("session is now exported at checkpoint %s", row.LatestCheckpoint)}
576		}
577		if factBranch != "" {
578			return exportSession{}, false, verifyCheck{Name: "session", Verdict: verifyVerdictOrphaned, Reason: fmt.Sprintf("session is missing from exported sessions on branch %s", factBranch)}
579		}
580		return exportSession{}, false, verifyCheck{Name: "session", Verdict: verifyVerdictOrphaned, Reason: "session is missing from exported sessions"}
581	}
582	
583	// exportedSessionAtCheckpoint returns the row whose LATEST checkpoint is the
584	// anchored one — the exact match, and the only one that needs no local
585	// checkpoint store to justify it. Several rows sharing that checkpoint fall
586	// back to the deterministic pick.
587	func exportedSessionAtCheckpoint(manifest *exportManifest, rows []exportSession, checkpointID string) (exportSession, bool) {
588		var matches []exportSession
589		for _, row := range rows {
590			if row.LatestCheckpoint == checkpointID {
591				matches = append(matches, row)
592			}
593		}
594		if len(matches) == 0 {
595			return exportSession{}, false
596		}
597		return pickExportedSession(manifest, matches), true
598	}
599	
600	// exportedSessionOwning returns the exported row a local (session, checkpoint)
601	// membership record belongs to, and ok=false when that cannot be decided. The
602	// membership record names the branch the checkpoint was made on, which is
603	// exactly what distinguishes one row of a multi-branch session from another; if
604	// it does not name one, or names one that does not select a single row, the
605	// caller keeps the conservative verdict instead of guessing.
606	func exportedSessionOwning(manifest *exportManifest, rows []exportSession, member sessionCheckpoint) (exportSession, bool) {
607		if len(rows) == 1 {
608			return rows[0], true
609		}
610		branch := strings.TrimSpace(member.Branch)
611		if branch == "" {
612			return exportSession{}, false
613		}
614		var matches []exportSession
615		for _, row := range rows {
616			if resolveDistillBranch(manifest, row) == branch {
617				matches = append(matches, row)
618			}
619		}
620		if len(matches) != 1 {
621			return exportSession{}, false
622		}
623		return matches[0], true
624	}
625	
626	// pickExportedSession chooses one of several rows the manifest lists for the
627	// same session id. Any total order over the rows' own contents will do; what
628	// matters is that it is not the manifest's array order, which is an artifact of
629	// how the export happened to be assembled.
630	func pickExportedSession(manifest *exportManifest, rows []exportSession) exportSession {
631		best := rows[0]
632		bestKey := exportedSessionKey(manifest, best)
633		for _, row := range rows[1:] {
634			if key := exportedSessionKey(manifest, row); key < bestKey {
635				best, bestKey = row, key
636			}
637		}
638		return best
639	}
640	
641	func exportedSessionKey(manifest *exportManifest, row exportSession) string {
642		return strings.Join([]string{
643			resolveDistillBranch(manifest, row),
644			row.LatestCheckpoint,
645			strconv.Itoa(row.SessionIndex),
646			row.TranscriptPath,
647			row.TurnID,
648		}, "\x00")
649	}
