651	func verifyTurnID(session exportSession, turnID string) verifyCheck {
652		if session.TurnID == "" {
653			return verifyCheck{Name: "turn", Verdict: verifyVerdictUnverifiableHere, Reason: "exported session has no turn_id; pending turn signing"}
654		}
655		if session.TurnID != turnID {
656			return verifyCheck{Name: "turn", Verdict: verifyVerdictStale, Reason: fmt.Sprintf("exported session now points at turn %s", session.TurnID)}
657		}
658		return verifyCheck{Name: "turn", Verdict: verifyVerdictVerified, Reason: "turn_id is present in exported session metadata"}
659	}
