661	func (v *verifyContext) verifyCheckpoint(checkpointID string) verifyCheck {
662		snapshot, err := v.localCheckpointSnapshot()
663		if err != nil {
664			return verifyCheck{Name: "checkpoint", Verdict: verifyVerdictUnverifiableHere, Reason: verifyCheckpointUnavailableHint + ": " + err.Error()}
665		}
666		if checkpointUnreadableInSnapshot(snapshot, checkpointID) {
667			return verifyCheck{Name: "checkpoint", Verdict: verifyVerdictUnverifiableHere, Reason: "checkpoint was listed locally but its retained source is unreadable"}
668		}
669		if !checkpointExistsInSnapshot(snapshot, checkpointID) {
670			return verifyCheck{Name: "checkpoint", Verdict: verifyVerdictOrphaned, Reason: "checkpoint is missing from local checkpoint refs"}
671		}
672		return verifyCheck{Name: "checkpoint", Verdict: verifyVerdictVerified, Reason: "checkpoint exists in local checkpoint refs"}
673	}
674	
675	func (v *verifyContext) verifyCheckpointTranscript(anchor factAnchor, session exportSession, exportedTranscript string) verifyCheck {
676		snapshot, err := v.localCheckpointSnapshot()
677		if err != nil {
678			return verifyCheck{Name: "checkpoint_transcript", Verdict: verifyVerdictUnverifiableHere, Reason: verifyCheckpointUnavailableHint + ": " + err.Error()}
679		}
680		if checkpointUnreadableInSnapshot(snapshot, anchor.CheckpointID) {
681			return verifyCheck{Name: "checkpoint_transcript", Verdict: verifyVerdictUnverifiableHere, Reason: "checkpoint was listed locally but its retained transcript source is unreadable"}
682		}
683		sourcePath, sourceKey := v.snapshotSourceTranscriptPath(snapshot, anchor, session)
684		if sourcePath == "" {
685			return verifyCheck{Name: "checkpoint_transcript", Verdict: verifyVerdictOrphaned, Reason: "checkpoint transcript path is missing"}
686		}
687		transcript, err := readSnapshotTranscriptFromSource(v.ctx, v.opts.Runner, snapshot, sourceKey, sourcePath)
688		if err != nil {
689			return verifyCheck{Name: "checkpoint_transcript", Verdict: verifyVerdictOrphaned, Reason: err.Error()}
690		}
691		if bytes.Equal(transcript, []byte(exportedTranscript)) {
692			return verifyCheck{Name: "checkpoint_transcript", Verdict: verifyVerdictVerified, Reason: "exported transcript matches local checkpoint transcript"}
693		}
694		// The export carries the session's transcript at its LATEST checkpoint. A
695		// sharpened anchor points at an earlier checkpoint of the same session,
696		// whose transcript is that same session earlier in time — a prefix, because
697		// a session's transcript only ever grows. Equality is still required for an
698		// anchor on the latest checkpoint, so nothing about the original check is
699		// relaxed; this only covers the earlier-checkpoint case the sharpener
700		// introduced.
701		if session.LatestCheckpoint != "" && anchor.CheckpointID != session.LatestCheckpoint &&
702			len(transcript) > 0 && bytes.HasPrefix([]byte(exportedTranscript), transcript) {
703			return verifyCheck{
704				Name:    "checkpoint_transcript",
705				Verdict: verifyVerdictVerified,
706				Reason:  fmt.Sprintf("local checkpoint %s transcript is a prefix of the exported session transcript", anchor.CheckpointID),
707			}
708		}
709		return verifyCheck{Name: "checkpoint_transcript", Verdict: verifyVerdictStale, Reason: "exported transcript differs from local checkpoint transcript"}
710	}
