712	func (v *verifyContext) localCheckpointSnapshot() (*checkpointSnapshot, error) {
713		if v.snapshotLoaded {
714			return v.snapshot, v.snapshotErr
715		}
716		v.snapshotLoaded = true
717		snapshot, warnings, err := loadLocalCheckpointSnapshotLocalOnly(v.ctx, v.opts.Runner, v.repoDir, true, checkpointBranchDestinations{}, nil)
718		v.snapshot = snapshot
719		v.snapshotErr = err
720		v.snapshotWarnings = append(v.snapshotWarnings, warnings...)
721		return v.snapshot, v.snapshotErr
722	}
