724	// sessionOwnsCheckpoint reports whether the local checkpoint store attributes a
725	// checkpoint to a session. It answers for EVERY checkpoint of the session, not
726	// just its latest, which is what lets a sharpened anchor verify.
727	func (v *verifyContext) sessionOwnsCheckpoint(sessionID, checkpointID string) bool {
728		sessionID, checkpointID = strings.TrimSpace(sessionID), strings.TrimSpace(checkpointID)
729		if sessionID == "" || checkpointID == "" {
730			return false
731		}
732		_, ok := v.sessionCheckpoint(sessionID, checkpointID)
733		return ok
734	}
735	
736	// sessionCheckpoint returns the local (session, checkpoint) membership record.
737	func (v *verifyContext) sessionCheckpoint(sessionID, checkpointID string) (sessionCheckpoint, bool) {
738		snapshot, err := v.localCheckpointSnapshot()
739		if err != nil || snapshot == nil {
740			return sessionCheckpoint{}, false
741		}
742		for _, member := range snapshot.SessionCheckpoints {
743			if member.SessionID == sessionID && member.CheckpointID == checkpointID {
744				return member, true
745			}
746		}
747		return sessionCheckpoint{}, false
748	}
