750	func (v *verifyContext) snapshotSourceTranscriptPath(snapshot *checkpointSnapshot, anchor factAnchor, session exportSession) (string, string) {
751		for _, candidate := range snapshot.Selected {
752			if candidate.SessionID == anchor.SessionID && candidate.CheckpointID == anchor.CheckpointID && candidate.SourceTranscriptPath != "" {
753				return candidate.SourceTranscriptPath, candidate.SourceKey
754			}
755		}
756		// Selected holds only each session's newest checkpoint. A sharpened anchor
757		// names an earlier one, whose transcript lives at ITS own path under ITS own
758		// session index — deriving the path from the exported (latest) session's
759		// index would read the wrong blob, or none.
760		for _, member := range snapshot.SessionCheckpoints {
761			if member.SessionID == anchor.SessionID && member.CheckpointID == anchor.CheckpointID && member.TranscriptPath != "" {
762				return member.TranscriptPath, member.SourceKey
763			}
764		}
765		path := snapshotTranscriptPath(anchor.CheckpointID, session.SessionIndex, snapshot.TranscriptFileName)
766		for sourceKey, source := range snapshot.Sources {
767			if hasSnapshotTranscript(path, source.TreePaths) {
768				return path, sourceKey
769			}
770		}
771		if hasSnapshotTranscript(path, snapshot.TreePaths) {
772			return path, ""
773		}
774		rootPath := snapshotRootTranscriptPath(anchor.CheckpointID, snapshot.TranscriptFileName)
775		for sourceKey, source := range snapshot.Sources {
776			if hasSnapshotTranscript(rootPath, source.TreePaths) {
777				return rootPath, sourceKey
778			}
779		}
780		if hasSnapshotTranscript(rootPath, snapshot.TreePaths) {
781			return rootPath, ""
782		}
783		return "", ""
784	}
785	
786	// loadLocalCheckpointSnapshotLocalOnly resolves the local checkpoint union
787	// for READERS: backend selection follows the configured primary, and the
788	// snapshot never touches the network. Discovery completeness is the caller's
789	// problem — a reader resolves checkpoints it already knows by id.
790	func loadLocalCheckpointSnapshotLocalOnly(ctx context.Context, runner CommandRunner, repoDir string, raw bool, branchDestinations checkpointBranchDestinations, cache *checkpointMetadataCache) (*checkpointSnapshot, []string, error) {
791		settings, settingsErr := readEntireSettings(repoDir)
792		primary, configured, primaryErr := configuredCheckpointPrimary(repoDir, settings)
793		if primaryErr != nil {
794			return nil, nil, fmt.Errorf("%w: checkpoint backend selection is invalid: %v", errCheckpointSnapshotUnavailable, primaryErr)
795		}
796		if !configured {
797			primary = checkpointBackendGitBranch
798		}
799		if settingsErr != nil && !errors.Is(settingsErr, os.ErrNotExist) && !configured {
800			return nil, nil, fmt.Errorf("%w: checkpoint settings are malformed or unreadable: %v", errCheckpointSnapshotUnavailable, settingsErr)
801		}
802		snapshot, warnings, err := loadLocalCheckpointUnionSnapshot(ctx, runner, repoDir, primary, raw, 0, branchDestinations, nil, cache, true)
803		if err != nil {
804			return nil, warnings, err
805		}
806		return snapshot, warnings, nil
807	}
