809	func checkpointExistsInSnapshot(snapshot *checkpointSnapshot, checkpointID string) bool {
810		for sourceKey := range snapshot.Sources {
811			if strings.HasSuffix(sourceKey, "\x00"+checkpointID) {
812				return true
813			}
814		}
815		prefix := checkpointPath(checkpointID) + "/"
816		for path := range snapshot.TreePaths {
817			if strings.HasPrefix(path, prefix) {
818				return true
819			}
820		}
821		return false
822	}
823	
824	func checkpointUnreadableInSnapshot(snapshot *checkpointSnapshot, checkpointID string) bool {
825		if snapshot == nil {
826			return false
827		}
828		_, unreadable := snapshot.UnreadableCheckpoints[checkpointID]
829		return unreadable
830	}
