832	func transcriptLine(content string, line int) (string, bool) {
833		if line <= 0 || content == "" {
834			return "", false
835		}
836		lines := strings.Split(content, "\n")
837		if line > len(lines) {
838			return "", false
839		}
840		return lines[line-1], true
841	}
