843	func addVerifyResultToSummary(summary *verifySummary, result verifyFactResult) {
844		summary.Facts++
845		switch result.Verdict {
846		case verifyVerdictVerified:
847			summary.Verified++
848		case verifyVerdictStale:
849			summary.Stale++
850		case verifyVerdictOrphaned:
851			summary.Orphaned++
852		case verifyVerdictUnverifiableHere:
853			summary.UnverifiableHere++
854		}
855	}
