857	func worseVerifyVerdict(a, b string) string {
858		if verifyVerdictRank(b) > verifyVerdictRank(a) {
859			return b
860		}
861		return a
862	}
863	
864	func verifyVerdictRank(verdict string) int {
865		switch verdict {
866		case verifyVerdictOrphaned:
867			return 4
868		case verifyVerdictStale:
869			return 3
870		case verifyVerdictUnverifiableHere:
871			return 2
872		case verifyVerdictVerified:
873			return 1
874		default:
875			return 0
876		}
877	}
