879	func reasonForFactVerdict(verdict string) string {
880		switch verdict {
881		case verifyVerdictVerified:
882			return "all locally checkable anchors resolved"
883		case verifyVerdictStale:
884			return "one or more anchors resolve to changed local source"
885		case verifyVerdictOrphaned:
886			return "one or more anchors are missing locally"
887		case verifyVerdictUnverifiableHere:
888			return "one or more anchors need finer local evidence"
889		default:
890			return "unknown verification verdict"
891		}
892	}
