894	func reasonForAnchorVerdict(verdict string) string {
895		switch verdict {
896		case verifyVerdictVerified:
897			return "anchor resolved locally"
898		case verifyVerdictStale:
899			return "anchor source changed locally"
900		case verifyVerdictOrphaned:
901			return "anchor source is missing locally"
902		case verifyVerdictUnverifiableHere:
903			return "anchor cannot be fully verified with local granularity"
904		default:
905			return "unknown verification verdict"
906		}
