909	func verificationSummaryForBranch(ctx context.Context, opts Options, repoDir, brainDir, branch string) (verifySummary, error) {
910		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
911		if err != nil {
912			return verifySummary{}, err
913		}
914		// Verify every active fact: sampling and inclusion of retired facts are separate options.
915		report, err := buildVerifyReport(ctx, opts, repoDir, brainDir, storage.Key, branch, verifyCommandOptions{}, "")
916		if err != nil {
