922	func renderVerifyReportText(cmd *cobra.Command, report verifyReport) {
923		out := cmd.OutOrStdout()
924		s := report.Summary
925		fmt.Fprintf(out, "verification: %d memories, %d verified, %d stale, %d orphaned, %d unverifiable-here\n",
926			s.Facts, s.Verified, s.Stale, s.Orphaned, s.UnverifiableHere)
927		// The summary above describes only the facts the store could still
928		// produce. If it could not produce everything the manifest declares, that
929		// line is a count of survivors, not a verdict — say so directly beneath it
930		// rather than leaving "0 orphaned" to stand as the answer.
931		if report.StoreIntegrity != nil {
932			fmt.Fprintf(out, "store integrity: %s\n", report.StoreIntegrity.Warning())
933			fmt.Fprintf(out, "  the counts above cover only the %d memory(ies) still readable\n", report.StoreIntegrity.Readable)
934		}
935		for _, result := range report.Results {
936			fmt.Fprintf(out, "%s %s [%s]\n  %s\n", result.Verdict, result.Fact.ID, strings.Join(result.Fact.Paths, ","), result.Fact.Text)
937			if result.Reason != "" {
938				fmt.Fprintf(out, "  reason: %s\n", result.Reason)
939			}
940			for _, anchor := range result.Anchors {
941				fmt.Fprintf(out, "  - %s session=%s checkpoint=%s commit=%s %s:%d\n",
942					anchor.Verdict,
943					valueOrUnset(anchor.Anchor.SessionID),
944					valueOrUnset(anchor.Anchor.CheckpointID),
945					valueOrUnset(anchor.Anchor.Commit),
946					valueOrUnset(anchor.Anchor.Transcript),
947					anchor.Anchor.Line)
948				if anchor.Reason != "" {
949					fmt.Fprintf(out, "    reason: %s\n", anchor.Reason)
950				}
951			}
952		}
953		for _, warning := range report.Warnings {
954			fmt.Fprintf(out, "warning: %s\n", warning)
955		}
956	}
