45	func newFactsRetractCommand(opts Options) *cobra.Command {
46		var (
47			branch  string
48			jsonOut bool
49			global  bool
50		)
51		cmd := &cobra.Command{
52			Use:   "retract <memory-id>",
53			Short: "Mark a memory as retracted (no longer true); pruned later by gc",
54			Args:  cobra.ExactArgs(1),
55			RunE: func(cmd *cobra.Command, args []string) error {
56				factID := args[0]
57				var (
58					brainDir       string
59					resolvedBranch string
60					err            error
61				)
62				// A fact that can be written and not retracted is a fact you are
63				// stuck with. Global facts surface in every repository, so being
64				// stuck with a wrong one is worse, not better.
65				if global {
66					if strings.TrimSpace(branch) != "" {
67						return fmt.Errorf("--global and --branch cannot be combined: a global memory is not on a branch")
68					}
69					brainDir, resolvedBranch, err = resolveGlobalFactsTarget(opts.Env)
70				} else {
71					_, brainDir, resolvedBranch, err = resolveFactsTarget(cmd.Context(), opts, agentSurfaceTarget(opts, nil), branch)
72				}
73				if err != nil {
74					return err
75				}
76				now := opts.Now().UTC()
77				changed := false
78				// Seeded with the id so the event is still identifiable if the
79				// record cannot be re-read after the mutation.
80				retracted := factRecord{ID: factID}
81				if err := brainstore.WithBrainWriteLock(brainDir, func() error {
82					facts, err := loadFacts(brainDir, resolvedBranch)
83					if err != nil {
84						return err
85					}
86					found, didChange := retractFact(facts, factID, now)
87					if !found {
88						if global {
89							return fmt.Errorf("no global memory %s", factID)
90						}
91						return fmt.Errorf("no memory %s on %s", factID, resolvedBranch)
92					}
93					changed = didChange
94					if !changed {
95						return nil
96					}
97					// Captured under the lock so the webhook reports the kind and
98					// paths of the fact that was actually retracted, rather than an
99					// id a subscriber would have to look up through an API that only
100					// listens on loopback.
101					if i := indexOfFact(facts, factID); i >= 0 {
102						retracted = facts[i]
103					}
104					if err := writeFacts(brainDir, resolvedBranch, facts); err != nil {
105						return err
106					}
107					return updateFactSourceManifestLocked(brainDir, now)
108				}); err != nil {
109					return err
110				}
111				// Only on a real transition: re-retracting an already-retracted fact
112				// changed nothing, and a subscriber that fired on it would act on
113				// news that is not news.
114				if changed {
115					if global {
116						webhook.NotifyGlobalFactWebhook(cmd.Context(), cmd.ErrOrStderr(), webhook.WebhookFactRetracted, retracted, now)
117					} else {
118						webhook.NotifyFactWebhook(cmd.Context(), cmd.ErrOrStderr(), opts, webhook.WebhookFactRetracted, resolvedBranch, retracted, now)
119					}
120				}
121				if jsonOut {
122					return cmdutil.WriteJSON(cmd, map[string]any{"id": factID, "branch": resolvedBranch, "status": factStatusRetracted, "changed": changed})
123				}
124				where := "on " + resolvedBranch
125				if global {
126					where = "globally"
127				}
128				if changed {
129					fmt.Fprintf(cmd.OutOrStdout(), "retracted %s %s (run `memories gc --force` to prune)\n", factID, where)
130				} else {
131					fmt.Fprintf(cmd.OutOrStdout(), "%s %s was already retracted\n", factID, where)
132				}
133				return nil
134			},
135		}
136		cmd.Flags().StringVar(&branch, "branch", "", "Branch the memory belongs to (default: current branch)")
137		cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit the result as JSON")
138		cmd.Flags().BoolVar(&global, "global", false, "Retract a global memory rather than one of this repository's")
139		return cmd
140	}
