174	type factsReviewActions struct {
175		apply, reject       string
176		applyAll, rejectAll bool
177		jsonOut             bool
178	}
179	
180	// validate refuses a request that asks for the same proposal to be both applied
181	// and rejected.
182	//
183	// The resolver below tests applyThis before rejectThis, so every contradictory
184	// combination used to settle the apply half, drop the reject half on the floor
185	// and report "resolved 1 proposal(s)" — a user who mistyped which side they
186	// meant was told their decision had landed while the opposite one actually did.
187	// A contradiction is not a preference to break silently; it is a question only
188	// the caller can answer.
189	func (act factsReviewActions) validate() error {
190		switch {
191		case act.applyAll && act.rejectAll:
192			return fmt.Errorf("--apply-all and --reject-all cannot both be set")
193		case act.applyAll && act.reject != "":
194			return fmt.Errorf("--apply-all and --reject %s cannot both be set: --apply-all already settles that proposal", act.reject)
195		case act.rejectAll && act.apply != "":
196			return fmt.Errorf("--reject-all and --apply %s cannot both be set: --reject-all already settles that proposal", act.apply)
197		case act.apply != "" && act.apply == act.reject:
198			return fmt.Errorf("--apply and --reject cannot both name %s", act.apply)
199		}
200		return nil
201	}
202	
203	func runFactsReview(cmd *cobra.Command, opts Options, brainDir, branch string, act factsReviewActions) error {
204		if err := act.validate(); err != nil {
205			return err
206		}
207		now := opts.Now().UTC()
208	
209		// No resolution requested: list pending proposals.
210		if act.apply == "" && act.reject == "" && !act.applyAll && !act.rejectAll {
211			proposals, err := loadFactProposals(brainDir, branch)
212			if err != nil {
213				return err
214			}
215			facts, err := loadFacts(brainDir, branch)
216			if err != nil {
217				return err
218			}
219			if act.jsonOut {
220				return cmdutil.WriteJSON(cmd, map[string]any{"branch": branch, "proposals": proposals})
221			}
222			if len(proposals) == 0 {
223				fmt.Fprintf(cmd.OutOrStdout(), "no pending proposals on %s\n", branch)
224				return nil
225			}
226			for _, p := range proposals {
227				fmt.Fprintf(cmd.OutOrStdout(), "%s %s -> %s (confidence %.2f)\n", p.Action, p.CandidateID, p.TargetID, p.Confidence)
228				printProposalContext(cmd, facts, p)
229			}
230			return nil
231		}
232	
233		resolved, remaining, deferred := 0, 0, 0
234		if err := brainstore.WithBrainWriteLock(brainDir, func() error {
235			proposals, err := loadFactProposals(brainDir, branch)
236			if err != nil {
237				return err
238			}
239			facts, err := loadFacts(brainDir, branch)
240			if err != nil {
241				return err
242			}
243			keep := proposals[:0:0]
244			for _, p := range proposals {
245				applyThis := act.applyAll || p.CandidateID == act.apply
246				rejectThis := act.rejectAll || p.CandidateID == act.reject
247				switch {
248				case applyThis:
249					updated, applyErr := applyDistillReviewProposal(facts, p, now)
250					if applyErr != nil {
251						if ci := indexOfFact(facts, p.CandidateID); ci >= 0 && facts[ci].Status == factStatusCandidate {
252							// A staged target may need review first. Never drop the only
253							// way to resolve this unpublished candidate.
254							fmt.Fprintf(cmd.ErrOrStderr(), "keep pending proposal %s: %v; resolve its target first or reject to keep the candidate separately\n", p.CandidateID, applyErr)
255							keep = append(keep, p)
256							deferred++
257							continue
258						}
259						fmt.Fprintf(cmd.ErrOrStderr(), "skip stale proposal %s: %v\n", p.CandidateID, applyErr)
260						resolved++ // drop the stale proposal
261						continue
262					}
263					facts = updated
264					resolved++
265				case rejectThis:
266					// Explicit rejection means keep the candidate as a separate fact.
267					if ci := indexOfFact(facts, p.CandidateID); ci >= 0 && facts[ci].Status == factStatusCandidate {
268						facts[ci].Status = factStatusActive
269						facts[ci].UpdatedAt = now
270					}
271					facts = rejectProposal(facts, p)
272					resolved++
273				default:
274					keep = append(keep, p)
275				}
276			}
277			remaining = len(keep)
278			if resolved == 0 {
279				if deferred > 0 {
280					// Warnings explain how to resolve these deferred proposals.
281					// Leave their records and queue intact.
282					return nil
283				}
284				return fmt.Errorf("no proposal matched")
285			}
286			if err := writeFacts(brainDir, branch, facts); err != nil {
287				return err
288			}
289			if err := writeFactProposals(brainDir, branch, keep); err != nil {
290				return err
291			}
292			return updateFactSourceManifestLocked(brainDir, now)
293		}); err != nil {
294			return err
295		}
296		if deferred > 0 {
297			fmt.Fprintf(cmd.OutOrStdout(), "resolved %d proposal(s) on %s; %d remaining (%d deferred; see warnings)\n", resolved, branch, remaining, deferred)
298		} else {
299			fmt.Fprintf(cmd.OutOrStdout(), "resolved %d proposal(s) on %s; %d remaining\n", resolved, branch, remaining)
300		}
301		return nil
302	}
303	
304	// Only local private review can publish a staged distill candidate. The shared
305	// settlement engine still requires active records on both sides.
306	func applyDistillReviewProposal(facts []factRecord, p factProposal, now time.Time) ([]factRecord, error) {
307		ci := indexOfFact(facts, p.CandidateID)
308		if ci < 0 || facts[ci].Status != factStatusCandidate {
309			return applyProposal(facts, p, now)
310		}
311		// Work on a copy so a rejected/stale apply cannot accidentally publish it.
312		ready := cloneDistillFacts(facts)
313		ready[ci].Status = factStatusActive
314		updated, err := applyProposal(ready, p, now)
315		if err != nil {
316			return facts, err
317		}
318		return updated, nil
319	}
