321	func printProposalContext(cmd *cobra.Command, facts []factRecord, p factProposal) {
322		if i := indexOfFact(facts, p.CandidateID); i >= 0 {
323			fmt.Fprintf(cmd.OutOrStdout(), "  candidate (%s): %s\n", facts[i].Status, facts[i].Text)
324		}
325		if i := indexOfFact(facts, p.TargetID); i >= 0 {
326			fmt.Fprintf(cmd.OutOrStdout(), "  target (%s): %s\n", facts[i].Status, facts[i].Text)
327		}
328	}
