381	// factsBranchIsReal reports whether a branch name still names something: a ref
382	// git knows, or a fact store this brain already holds. The second half matters
383	// because a merged feature branch is commonly deleted while its facts live on,
384	// and promoting those forward is the whole point of the command.
385	func factsBranchIsReal(ctx context.Context, opts Options, repoDir, brainDir, branch string) bool {
386		if factBranchStoreExists(brainDir, branch) {
387			return true
388		}
389		return gitRefExists(ctx, opts.Runner, repoDir, "refs/heads/"+branch) ||
390			gitRefExists(ctx, opts.Runner, repoDir, "refs/remotes/origin/"+branch)
391	}
392	
393	// validateFactsPromoteEndpoints checks the two branch names promote was handed.
394	// Neither used to be checked at all, and each typo failed in its own quiet way:
395	//
396	//   - a bad --from loaded nothing (loadFacts reads a missing store as an empty
397	//     branch) and reported "promoted 0 fact(s)" — the same success line a real
398	//     but empty source produces, so the user had no way to tell a typo from a
399	//     branch that genuinely had nothing to give;
400	//   - a bad --into was worse than quiet. writeFacts creates the target store on
401	//     demand, so promote happily forked the fact set into a directory keyed to a
402	//     branch that does not exist. Nothing reads it back, no later command names
403	//     it, and no branch can ever reach it: the facts are gone while the command
404	//     reports success.
405	//
406	// So both endpoints must name something real, and --from must additionally have
407	// facts — "nothing to promote" is a distinct, stateable outcome, not a success.
408	func validateFactsPromoteEndpoints(ctx context.Context, opts Options, repoDir, brainDir, from, into string) error {
409		if !factsBranchIsReal(ctx, opts, repoDir, brainDir, from) {
410			return fmt.Errorf("--from %q is not a branch: git does not know it and this brain holds no memories for it", from)
411		}
412		if !factBranchStoreExists(brainDir, from) {
413			return fmt.Errorf("--from %q has no memories to promote", from)
414		}
415		if !factsBranchIsReal(ctx, opts, repoDir, brainDir, into) {
416			return fmt.Errorf("--into %q is not a branch: git does not know it and this brain holds no memories for it; promoting into it would strand a memory store no branch can reach", into)
417		}
418		return nil
419	}
420	
421	func runFactsPromote(cmd *cobra.Command, opts Options, brainDir, from, into, strategy string, jsonOut bool) error {
422		now := opts.Now().UTC()
423		var promoted, proposalCount int
424		if err := brainstore.WithBrainWriteLock(brainDir, func() error {
425			source, err := loadFacts(brainDir, from)
426			if err != nil {
427				return err
428			}
429			target, err := loadFacts(brainDir, into)
430			if err != nil {
431				return err
432			}
433			merged, proposals, promotedCount := promoteFacts(source, target, strategy, into, now)
434			promoted = promotedCount
435			proposalCount = len(proposals)
436			if err := writeFacts(brainDir, into, merged); err != nil {
437				return err
438			}
439			if len(proposals) > 0 {
440				existing, _ := loadFactProposals(brainDir, into)
441				if err := writeFactProposals(brainDir, into, dedupeProposals(append(existing, proposals...))); err != nil {
442					return err
443				}
444			}
445			return updateFactSourceManifestLocked(brainDir, now)
446		}); err != nil {
447			return err
448		}
449		summary := map[string]any{"from": from, "into": into, "strategy": strategy, "promoted": promoted, "proposals": proposalCount}
450		if jsonOut {
451			return cmdutil.WriteJSON(cmd, summary)
452		}
453		fmt.Fprintf(cmd.OutOrStdout(), "promoted %d memory(ies) from %s into %s (%s); %d conflict(s) queued for review\n", promoted, from, into, strategy, proposalCount)
454		return nil
455	}
