528	func runFactsReclassify(cmd *cobra.Command, opts Options, brainDir, branch string, force, jsonOut bool) error {
529		now := opts.Now().UTC()
530		var facts []factRecord
531		changed := 0
532		// The whole load-mutate-write runs under the brain write lock, like every
533		// other fact mutator (remember, retract, review, promote, gc, distill's
534		// flush) and like the refresh-time reclassifyAllFactBranches. Reading the
535		// store outside it and writing the mutated copy back is a lost update: a
536		// concurrent writer that commits between this read and this write is
537		// silently overwritten, and its facts disappear.
538		if err := brainstore.WithBrainWriteLock(brainDir, func() error {
539			loaded, err := loadFacts(brainDir, branch)
540			if err != nil {
541				return err
542			}
543			facts = loaded
544			changed = reclassifyFacts(facts, force)
545			if changed > 0 {
546				if err := writeFacts(brainDir, branch, facts); err != nil {
547					return err
548				}
549			}
550			// Always refresh the manifest, even on a no-op reclassify: a store predating
551			// the by_kind field has valid kinds but a stale/absent histogram that only a
552			// manifest rebuild repairs.
553			return updateFactSourceManifestLocked(brainDir, now)
554		}); err != nil {
555			return err
556		}
557		byKind := map[string]int{}
558		for _, f := range facts {
559			if f.Status == factStatusActive {
560				byKind[factKindOrInferred(f)]++
561			}
562		}
563		if jsonOut {
564			return cmdutil.WriteJSON(cmd, map[string]any{"branch": branch, "changed": changed, "facts": len(facts), "by_kind": byKind})
565		}
566		fmt.Fprintf(cmd.OutOrStdout(), "reclassified %d of %d memory(ies) on %s\n", changed, len(facts), branch)
567		for _, kind := range []string{factKindDecision, factKindInvariant, factKindGotcha, factKindPreference, factKindConvention} {
568			if byKind[kind] > 0 {
569				fmt.Fprintf(cmd.OutOrStdout(), "  %-11s %d\n", kind, byKind[kind])
570			}
571		}
572		return nil
573	}
