629	func newFactsMapCommand(opts Options) *cobra.Command {
630		var (
631			branch  string
632			path    string
633			depth   int
634			jsonOut bool
635		)
636		cmd := &cobra.Command{
637			Use:   "map",
638			Short: "Render the synthesized memory outline (summaries + structure) with progressive disclosure",
639			Args:  cobra.NoArgs,
640			RunE: func(cmd *cobra.Command, args []string) error {
641				_, brainDir, resolvedBranch, err := resolveFactsTarget(cmd.Context(), opts, agentSurfaceTarget(opts, nil), branch)
642				if err != nil {
643					return err
644				}
645				// Always rebuild the structure from the live facts (it is deterministic
646				// and never stale), then overlay stored summaries only where the node's
647				// fingerprint still matches — so a summary for a changed subtree is
648				// hidden rather than shown stale, and no `facts outline` run is required
649				// to see the map.
650				facts, err := loadFacts(brainDir, resolvedBranch)
651				if err != nil {
652					return err
653				}
654				outline := buildFactOutlineTree(resolvedBranch, facts, opts.Now().UTC())
655				if stored, storedErr := loadFactOutline(brainDir, resolvedBranch); storedErr == nil {
656					for key, n := range outline.Nodes {
657						if s, ok := stored.Nodes[key]; ok && s.Fingerprint == n.Fingerprint && s.Summary != "" {
658							n.Summary = s.Summary
659							outline.Nodes[key] = n
660						}
661					}
662				}
663				node := path
664				if _, ok := outline.Nodes[node]; !ok {
665					return fmt.Errorf("no outline node %q on %s", path, resolvedBranch)
666				}
667				// The outline counts what loadFacts produced. When the manifest
668				// declares more than that, "root (4 facts)" is a count of survivors
669				// rendered as if it were the corpus. Qualify it before rendering,
670				// and exit nonzero so a caller cannot read the map as complete.
671				integrityErr := reportFactStoreIntegrity(cmd, brainDir, jsonOut)
672				if jsonOut {
673					if err := cmdutil.WriteJSON(cmd, outline); err != nil {
674						return err
675					}
676					return integrityErr
677				}
678				var b strings.Builder
679				renderFactOutline(&b, outline, node, depth)
680				if b.Len() == 0 {
681					fmt.Fprintf(cmd.OutOrStdout(), "no memories on %s\n", resolvedBranch)
682					return integrityErr
683				}
684				fmt.Fprint(cmd.OutOrStdout(), b.String())
685				return integrityErr
686			},
687		}
688		cmd.Flags().StringVar(&branch, "branch", "", "Branch to map (default: current branch)")
689		cmd.Flags().StringVar(&path, "path", "", "Drill into a node key (a directory tier, e.g. internal/cli)")
690		cmd.Flags().IntVar(&depth, "depth", 0, "Levels to render below the node (0 = all)")
691		cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit the outline as JSON")
692		return cmd
693	}
