695	func runFactsGC(cmd *cobra.Command, opts Options, brainDir, branch string, force bool, retain time.Duration, jsonOut bool) error {
696		facts, err := loadFacts(brainDir, branch)
697		if err != nil {
698			return err
699		}
700		now := opts.Now().UTC()
701		taxonomy, err := loadFactTaxonomy(brainDir, now)
702		if err != nil {
703			return err
704		}
705		result := gcFacts(facts, taxonomy, now, retain)
706	
707		summary := map[string]any{
708			"branch":    branch,
709			"pruned":    len(result.Pruned),
710			"orphans":   len(result.Orphans),
711			"remaining": len(result.Kept),
712			"applied":   force,
713		}
714		if force {
715			if err := brainstore.WithBrainWriteLock(brainDir, func() error {
716				facts, err := loadFacts(brainDir, branch)
717				if err != nil {
718					return err
719				}
720				taxonomy, err := loadFactTaxonomy(brainDir, now)
721				if err != nil {
722					return err
723				}
724				result = gcFacts(facts, taxonomy, now, retain)
725				summary["pruned"] = len(result.Pruned)
726				summary["orphans"] = len(result.Orphans)
727				summary["remaining"] = len(result.Kept)
728				if err := writeFacts(brainDir, branch, result.Kept); err != nil {
729					return err
730				}
731				return updateFactSourceManifestLocked(brainDir, now)
732			}); err != nil {
733				return err
